import java.util.Scanner;

public class OneBasedArithmetic {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = 10 * ones[i - 1] + 1;
        }
        System.out.println(calculate(ones, n, 16));
        sc.close();
    }

    private static long calculate(long[] ones, long n, int idx) {
        long quotient = n / ones[idx];
        long remainder = n % ones[idx];
        long total = quotient * idx;
        if (remainder == 0) {
            return total;
        } else {
            long optionA = calculate(ones, remainder, idx - 1);
            long optionB = idx + calculate(ones, ones[idx] - remainder, idx - 1);
            return total + Math.min(optionA, optionB);
        }
    }
}
