#include <iostream>
#include <algorithm>

int main() {
    long n;
    std::cin >> n;
    long ones[17];
    for (int i = 1; i < 17; i++) {
        ones[i] = 10 * ones[i - 1] + 1;
    }

    std::function<long(long[], long, int)> calculate = [&](long arr[], long n, int idx) -> long {
        long quotient = n / arr[idx];
        long remainder = n % arr[idx];
        long total = quotient * idx;
        if (remainder == 0) {
            return total;
        } else {
            long optionA = calculate(arr, remainder, idx - 1);
            long optionB = idx + calculate(arr, arr[idx] - remainder, idx - 1);
            return total + std::min(optionA, optionB);
        }
    };

    std::cout << calculate(ones, n, 16) << std::endl;
    return 0;
}
